const createAudioDeviceStore = () => {
  let snapshot = { devices: [] as MediaDeviceInfo[], loading: true, error: null as string | null, hasPermission: false };
  const serverSnapshot = snapshot;
  const listeners = new Set<() => void>();
  let request: Promise<void> | null = null;
  let generation = 0;
  const publish = (patch: Partial<typeof snapshot>) => {
    snapshot = { ...snapshot, ...patch };
    for (const listener of listeners) listener();
  };
  const enumerate = async (version: number) => {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      if (version === generation) publish({ devices: devices.filter((device) => device.kind === "audioinput"), loading: false, error: null });
    } catch (error) {
      if (version === generation) publish({ loading: false, error: error instanceof Error ? error.message : "Failed to get audio devices" });
    }
  };
  const onDeviceChange = () => {
    publish({ loading: true, error: null });
    void enumerate(++generation);
  };
  return {
    getSnapshot: () => snapshot,
    getServerSnapshot: () => serverSnapshot,
    subscribe: (listener: () => void) => {
      listeners.add(listener);
      if (listeners.size === 1) {
        navigator.mediaDevices?.addEventListener("devicechange", onDeviceChange);
        void enumerate(++generation);
      }
      return () => {
        listeners.delete(listener);
        if (listeners.size === 0) {
          generation++;
          navigator.mediaDevices?.removeEventListener("devicechange", onDeviceChange);
        }
      };
    },
    loadDevices: () => {
      if (request) return request;
      const version = ++generation;
      publish({ loading: true, error: null });
      request = (async () => {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          for (const track of stream.getTracks()) track.stop();
          if (version !== generation) return;
          publish({ hasPermission: true });
          await enumerate(version);
        } catch (error) {
          if (version === generation) publish({ loading: false, error: error instanceof Error ? error.message : "Failed to get audio devices" });
        } finally {
          request = null;
        }
      })();
      return request;
    },
  };
};

export const useAudioDevices = () => {
  const [store] = useState(createAudioDeviceStore);
  const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getServerSnapshot);
  return { ...snapshot, loadDevices: store.loadDevices };
};

export type MicSelectorProps = ComponentProps<typeof Popover> & {
  defaultValue?: string;
  value?: string | undefined;
  onValueChange?: (value: string | undefined) => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
};

export const MicSelector = ({
  defaultValue,
  value: controlledValue,
  onValueChange: controlledOnValueChange,
  defaultOpen = false,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  ...props
}: MicSelectorProps) => {
  const [value, onValueChange] = useControllableState<string | undefined>({
    defaultProp: defaultValue,
    onChange: controlledOnValueChange,
    prop: controlledValue,
  });
  const [open, onOpenChange] = useControllableState({
    defaultProp: defaultOpen,
    onChange: controlledOnOpenChange,
    prop: controlledOpen,
  });
  const [width, setWidth] = useState(200);
  const { devices, hasPermission, loadDevices } = useAudioDevices();

  useEffect(() => {
    if (open && !hasPermission) {
      loadDevices();
    }
  }, [open, hasPermission, loadDevices]);

  const contextValue = useMemo(
    () => ({
      data: devices,
      onOpenChange,
      onValueChange,
      open,
      setWidth,
      value,
      width,
    }),
    [devices, onOpenChange, onValueChange, open, setWidth, value, width]
  );

  return (
    <MicSelectorContext.Provider value={contextValue}>
      <Popover {...props} onOpenChange={onOpenChange} open={open} />
    </MicSelectorContext.Provider>
  );
};

export type MicSelectorTriggerProps = ComponentProps<typeof Button>;

export const MicSelectorTrigger = ({
  children,
  ...props
}: MicSelectorTriggerProps) => {
  const { setWidth } = useContext(MicSelectorContext);
  const ref = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    // Create a ResizeObserver to detect width changes
    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const newWidth = (entry.target as HTMLElement).offsetWidth;
        if (newWidth) {
          setWidth?.(newWidth);
        }
      }
    });

    if (ref.current) {
      resizeObserver.observe(ref.current);
    }

    // Clean up the observer when component unmounts
    return () => {
      resizeObserver.disconnect();
    };
  }, [setWidth]);

  return (
    <PopoverTrigger asChild>
      <Button variant="outline" {...props} ref={ref}>
        {children}
        <ChevronsUpDownIcon
          className="shrink-0 text-muted-foreground"
          size={16}
        />
      </Button>
    </PopoverTrigger>
  );
};

