const createImageSource = (source: string | Blob) => {
  let url = typeof source === "string" ? source : "";
  return {
    getSnapshot: () => url,
    getServerSnapshot: () => typeof source === "string" ? source : "",
    subscribe: (onChange: () => void) => {
      if (typeof source === "string") return () => {};
      url = URL.createObjectURL(source);
      onChange();
      return () => { URL.revokeObjectURL(url); url = ""; };
    },
  };
};

export const QueueItemImage = ({
  className,
  src = "",
  alt = "",
  height = 32,
  width = 32,
  ...props
}: QueueItemImageProps) => {
  const source = useMemo(() => createImageSource(src), [src]);
  const imageUrl = useSyncExternalStore(source.subscribe, source.getSnapshot, source.getServerSnapshot);
  if (!imageUrl) return null;
  return (
  <NextImage
    alt={alt}
    src={imageUrl}
    className={cn("h-8 w-8 rounded border object-cover", className)}
    height={Number(height)}
    width={Number(width)}
    unoptimized
    {...props}
  />
  );
};

